pub fn handle_initialize_customizable_pool<'info>(
    ctx: Context<'info, InitializeCustomizablePoolCtx<'info>>,
    params: InitializeCustomizablePoolParameters,
) -> Result<()> {
    params.validate()?;
    validate_mint(
        &ctx.accounts.token_a_mint,
        false,
        ctx.remaining_accounts.get(0),
    )?;
    validate_mint(
        &ctx.accounts.token_b_mint,
        false,
        ctx.remaining_accounts.get(1),
    )?;

    let InitializeCustomizablePoolParameters {
        pool_fees,
        liquidity,
        sqrt_price,
        activation_point,
        sqrt_min_price,
        sqrt_max_price,
        activation_type,
        collect_fee_mode,
        has_alpha_vault,
        ..
    } = params;

    let InitialPoolInformation {
        token_a_amount,
        token_b_amount,
        initial_liquidity,
        sqrt_min_price,
        sqrt_max_price,
        sqrt_price,
    } = get_initial_pool_information(
        collect_fee_mode.safe_cast()?,
        sqrt_min_price,
        sqrt_max_price,
        sqrt_price,
        liquidity,
    )?;

    require!(
        token_a_amount > 0 || token_b_amount > 0,
        PoolError::AmountIsZero
    );

    let mut pool = ctx.accounts.pool.load_init()?;

    let token_a_flag: u8 = get_token_program_flags(&ctx.accounts.token_a_mint).into();
    let token_b_flag: u8 = get_token_program_flags(&ctx.accounts.token_b_mint).into();
    let activation_point =
        activation_point.unwrap_or(ActivationHandler::get_current_point(activation_type)?);
    let alpha_vault = get_whitelisted_alpha_vault(
        ctx.accounts.payer.key(),
        ctx.accounts.pool.key(),
        has_alpha_vault,
    );
    let pool_type: u8 = PoolType::Customizable.into();

    pool.initialize(
        ctx.accounts.creator.key(),
        pool_fees.to_pool_fees_struct(sqrt_price)?,
        ctx.accounts.token_a_mint.key(),
        ctx.accounts.token_b_mint.key(),
        ctx.accounts.token_a_vault.key(),
        ctx.accounts.token_b_vault.key(),
        alpha_vault,
        sqrt_min_price,
        sqrt_max_price,
        sqrt_price,
        activation_point,
        activation_type,
        token_a_flag,
        token_b_flag,
        liquidity,
        collect_fee_mode,
        pool_type,
        token_a_amount,
        token_b_amount,
    );

    let mut position = ctx.accounts.position.load_init()?;
    position.initialize(
        &mut pool,
        ctx.accounts.pool.key(),
        ctx.accounts.position_nft_mint.key(),
        initial_liquidity,
    );

    // create position nft
    drop(position);
    create_position_nft(
        ctx.accounts.payer.to_account_info(),
        ctx.accounts.position_nft_mint.to_account_info(),
        ctx.accounts.pool_authority.to_account_info(),
        ctx.accounts.system_program.to_account_info(),
        ctx.accounts.token_2022_program.to_account_info(),
        ctx.accounts.position_nft_account.to_account_info(),
    )?;

    emit_cpi!(EvtCreatePosition {
        pool: ctx.accounts.pool.key(),
        owner: ctx.accounts.creator.key(),
        position: ctx.accounts.position.key(),
        position_nft_mint: ctx.accounts.position_nft_mint.key(),
    });

    // transfer token

    let mut total_amount_a = calculate_transfer_fee_included_amount(
        &ctx.accounts
            .token_a_mint
            .to_account_info()
            .try_borrow_data()?,
        token_a_amount,
    )?
    .amount;

    let mut total_amount_b = calculate_transfer_fee_included_amount(
        &ctx.accounts
            .token_b_mint
            .to_account_info()
            .try_borrow_data()?,
        token_b_amount,
    )?
    .amount;

    // require at least 1 lamport to prove ownership of token mints
    total_amount_a = total_amount_a.max(1);
    total_amount_b = total_amount_b.max(1);

    transfer_from_user(
        &ctx.accounts.payer,
        &ctx.accounts.token_a_mint,
        &ctx.accounts.payer_token_a,
        &ctx.accounts.token_a_vault,
        &ctx.accounts.token_a_program,
        total_amount_a,
    )?;
    transfer_from_user(
        &ctx.accounts.payer,
        &ctx.accounts.token_b_mint,
        &ctx.accounts.payer_token_b,
        &ctx.accounts.token_b_vault,
        &ctx.accounts.token_b_program,
        total_amount_b,
    )?;

    emit_cpi!(EvtInitializePool {
        pool: ctx.accounts.pool.key(),
        token_a_mint: ctx.accounts.token_a_mint.key(),
        token_b_mint: ctx.accounts.token_b_mint.key(),
        pool_fees,
        creator: ctx.accounts.creator.key(),
        payer: ctx.accounts.payer.key(),
        activation_point,
        activation_type,
        token_a_flag,
        token_b_flag,
        sqrt_price,
        liquidity,
        sqrt_min_price,
        sqrt_max_price,
        alpha_vault,
        collect_fee_mode,
        token_a_amount,
        token_b_amount,
        total_amount_a,
        total_amount_b,
        pool_type,
    });

    Ok(())
}

pub fn get_whitelisted_alpha_vault(payer: Pubkey, pool: Pubkey, has_alpha_vault: bool) -> Pubkey {
    if has_alpha_vault {
        alpha_vault::derive_vault_pubkey(payer, pool)
    } else {
        Pubkey::default()
    }
}

